{
  "questions": [
    {
      "id": 1,
      "enunciado": "O que é uma variável na programação?",
      "alternativas": {
        "A": "Um tipo de dado primitivo",
        "B": "Um contêiner nomeado que armazena um valor na memória",
        "C": "Uma estrutura de controle de fluxo",
        "D": "Um loop de repetição",
        "E": "Uma função matemática"
      },
      "correta": "B",
      "explicacao": "Variáveis são contêineres nomeados usados para armazenar valores na memória do computador, permitindo que sejam referenciados e manipulados durante a execução do programa."
    },
    {
      "id": 2,
      "enunciado": "Qual dos seguintes NÃO é um tipo de dado primitivo?",
      "alternativas": {
        "A": "int",
        "B": "float",
        "C": "string",
        "D": "boolean",
        "E": "função"
      },
      "correta": "E",
      "explicacao": "Função não é um tipo de dado primitivo. Os tipos primitivos comuns são int (inteiro), float (decimal), string (texto) e boolean (verdadeiro/falso)."
    },
    {
      "id": 3,
      "enunciado": "Qual estrutura de controle é usada para executar um bloco de código repetidamente enquanto uma condição for verdadeira?",
      "alternativas": {
        "A": "if/else",
        "B": "switch",
        "C": "while",
        "D": "try/catch",
        "E": "break"
      },
      "correta": "C",
      "explicacao": "O loop 'while' executa um bloco de código repetidamente enquanto a condição especificada for verdadeira. 'if/else' e 'switch' são para decisão, não repetição."
    },
    {
      "id": 4,
      "enunciado": "Qual a diferença principal entre if simples e if/else?",
      "alternativas": {
        "A": "if executa apenas uma linha, if/else executa múltiplas",
        "B": "if executa um bloco quando a condição é verdadeira; if/else também executa um bloco alternativo quando é falsa",
        "C": "if/else é mais rápido que if simples",
        "D": "if só funciona com números, if/else funciona com qualquer tipo",
        "E": "Não há diferença, são sinônimos"
      },
      "correta": "B",
      "explicacao": "O if simples executa um bloco apenas quando a condição é verdadeira. O if/else adiciona um bloco alternativo que é executado quando a condição é falsa, permitindo cobrir ambos os casos."
    },
    {
      "id": 5,
      "enunciado": "Como declarar uma função em JavaScript?",
      "alternativas": {
        "A": "function = minhaFuncao()",
        "B": "def minhaFuncao():",
        "C": "function minhaFuncao() { }",
        "D": "função minhaFuncao()",
        "E": "func minhaFuncao()"
      },
      "correta": "C",
      "explicacao": "Em JavaScript, funções são declaradas com a palavra-chave 'function', seguida pelo nome, parênteses para parâmetros e chaves para o corpo: function minhaFuncao() { }"
    }
  ]
}
